 for(const [fid,i] of this.index.get('ElmSubstat')||[]){const g=this.row('ElmSubstat',i);const s=this.stationGroups.get(g.fold_id);if(s){s.groups.push(g);const lat=Number(g.GPSlat),lon=Number(g.GPSlon);if(Number.isFinite(lat)&&Number.isFinite(lon)&&lat>=30&&lat<=46&&lon>=25&&lon<=46){if(s.lat===null){s.lat=lat;s.lon=lon;}else if(Math.hypot(s.lat-lat,s.lon-lon)>0.12)this.addIssue('TM bara grubu koordinat farkı','ElmSubstat',fid,`${g.loc_name}: ilk grup ile farklı konum`);}else this.addIssue('Geçersiz TM koordinatı','ElmSubstat',fid,`${lat}, ${lon}`);}}
