 for(const line of this.lines){if(line.geoStatus==='Eksik')this.addIssue('Hat güzergâhı bulunamadı','ElmLne',line.FID,'Güzergâh yok; iki TM koordinatı varsa temsili bağlantı çizilir.','Bilgi');else if(line.geoStatus==='Tek koordinat')this.addIssue('Hat güzergâhı tek noktalı','ElmLne',line.FID,'Tek nokta gerçek çizgi güzergâhı oluşturmaz; temsili bağlantı çizilir.','Bilgi');}
