 this.stats={sites:this.sites.length,real:this.sites.filter(s=>s.sType==='GERCEK').length,virtual:this.sites.filter(s=>s.sType!=='GERCEK').length,lines:this.lines.length,geo:this.lines.filter(x=>x.geoStatus==='Model güzergâhı').length,fallback:this.lines.filter(x=>x.geoStatus!=='Model güzergâhı').length,tr:this.t('ElmTr2')?.Values.length||0,bay:this.t('ElmBay')?.Values.length||0,unit:(this.t('ElmSym')?.Values.length||0)+(this.t('ElmGenStat')?.Values.length||0),load:this.t('ElmLod')?.Values.length||0,rows:Array.from(this.tables.values()).reduce((s,t)=>s+t.Values.length,0)};
 // Large raw matrix stays available for audit but is no longer needed for normal UI interaction.
