function renderModelList(){if(!models.length){$('modelList').className='empty';$('modelList').textContent='Henüz model yüklenmedi.';return;}$('modelList').className='';$('modelList').innerHTML=models.map((m,i)=>`<div class="row" style="padding:7px;border-bottom:1px solid var(--edge)"><span class="badge ${m===active?'':'warn'}">${m===active?'Aktif':'Yüklü'}</span><b>${h(m.date)} ${h(m.time)}</b><span class="sub">${h(m.name)} · ${nf.format(m.stats.rows)} kayıt</span><button class="sm right" data-model="${i}">Etkinleştir</button><button class="sm" data-remove="${i}">Kaldır</button></div>`).join('');$$('[data-model]',$('modelList')).forEach(b=>b.onclick=()=>activateModel(models[+b.dataset.model]));$$('[data-remove]',$('modelList')).forEach(b=>b.onclick=()=>{let m=models[+b.dataset.remove];if(!confirm(`"${m.name}" modelini bellekten kaldırmak istiyor musunuz?`))return;models.splice(models.indexOf(m),1);if(active===m)activateModel(models[0]||null);else{renderModelList();populateFilters();fillCompareOptions();listSets();}});}
