function activateModel(m){active=m;selectedLine=null;selectedSite=null;statState.page=0;dynState.page=0;statState.selected=null;dynState.selected=null;fillModelInfo();if(active){renderStatic();renderDyn();resetCamera();}else{$('summaryCards').innerHTML='';$('modelMeta').innerHTML='';$('staticTable').innerHTML='';$('dynTable').innerHTML='';$('mapSelection').textContent='Model yükleyin.';renderModelList();}if(currentView==='map')setView('map');}
async function loadFiles(files){if(!files.length)return;$('loadProgress').classList.remove('hidden');for(let fi=0;fi<files.length;fi++){let f=files[fi];try{const step=s=>{putText('progressText',`${fi+1}/${files.length} · ${f.name} · ${s}`);status(`İşleniyor · ${f.name} · ${s}`);};step('Dosya okunuyor');await defer();const str=await f.text();step('JSON ayrıştırılıyor');await defer();let raw=await parseJSONOffMain(str,step);step('DGS sınıf ve kayıtları doğrulanıyor');await defer();let m=new DGSModel(raw,f.name,f.size);await m.init(step);auditV2(m);models.push(m);models.sort((a,b)=>a.timeKey.localeCompare(b.timeKey));activateModel(m);window.V6Bridge?.modelLoaded(m,f);notice(`Yüklendi: ${f.name} · ${nf.format(m.stats.rows)} kayıt · ${nf.format(m.stats.geo)} güzergâhlı hat.`, '');
 }catch(e){console.error(e);notice(`Dosya yüklenemedi: ${f.name} · ${e.message}`,'bad');status('Dosya hatası · '+e.message);}await defer();}$('loadProgress').classList.add('hidden');if(active)putText('progressText','Tamamlandı');}
$('fileInput').addEventListener('change',e=>{loadFiles(Array.from(e.target.files));e.target.value='';});$('chooseFile').onclick=e=>{e.preventDefault();$('fileInput').click();};const drop=$('filedrop');for(const ev of ['dragenter','dragover'])drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.add('drag')});for(const ev of ['dragleave','drop'])drop.addEventListener(ev,e=>{e.preventDefault();drop.classList.remove('drag')});drop.addEventListener('drop',e=>loadFiles(Array.from(e.dataTransfer.files)));
function clearAll(){models.splice(0);activateModel(null);notice('Bellekteki modeller temizlendi. Tekrar yüklemek için JSON dosyasını seçin.');}
$('clearModels').onclick=()=>{if(models.length && confirm('Tüm modelleri bellekten kaldırmak istiyor musunuz?'))clearAll();};$('settingsClear').onclick=()=>{if(models.length&&confirm('Tüm modelleri bellekten kaldırmak istiyor musunuz?')){clearAll();setView('upload');}};
function toCSV(rows,cols,name){const cell=v=>'"'+String(v??'').replace(/"/g,'""')+'"';let csv='\uFEFF'+cols.map(c=>cell(LABEL[c]||c)).join(';')+'\r\n'+rows.map(r=>cols.map(c=>cell(r[c])).join(';')).join('\r\n');let blob=new Blob([csv],{type:'text/csv;charset=utf-8'});let url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download=basename(name);a.click();setTimeout(()=>URL.revokeObjectURL(url),4000);}
$('exportIssues').onclick=()=>{if(active)toCSV(active.issues,['level','kind','cls','fid','details'],`YTBS_${active.date}_dogrulama.csv`)};
const groupDisplay=r=>r==null?'—':String(r);
function staticRow(m,cls,i){return m.enriched(cls,i);}
function filterStatic(resetPage=false){if(!active)return;let cls=$('staticType').value;let t=active.t(cls);statState.cat=cls;if(resetPage)statState.page=0;
 if(!t){statState.rows=[];return;}const idIx=active.attrAt(cls,'FID'),nameIx=active.attrAt(cls,'loc_name'),search=norm($('staticSearch').value.trim());let tm=$('staticSite').value,area=$('staticArea').value,voltage=$('staticVoltage').value;
 let out=[];for(let i=0;i<t.Values.length;i++){let raw=t.Values[i],id=raw[idIx]??'',name=nameIx>=0?raw[nameIx]:'';if(search&&!norm(id+' '+name).includes(search))continue;
 if(tm||area||voltage){let sid=null;if(cls==='ElmSite')sid=String(id);else if(cls==='ElmLne'){let li=active.lineById(id);sid=li?.stationA||li?.stationB; if(tm&&li?.stationA!==tm&&li?.stationB!==tm)continue;}else if(cls==='ElmTr2'){let r=active.row(cls,i),a=active.siteFromCub(r.bushv),b=active.siteFromCub(r.buslv);sid=a||b;if(tm&&tm!==a&&tm!==b)continue;}else sid=active.resolveSiteByClass(cls,String(id),raw,active.attrAt(cls,'fold_id'));
 if(tm&&cls!=='ElmLne'&&cls!=='ElmTr2'&&sid!==tm)continue;
 if(area){let sidForArea=sid;if(cls==='ElmLne'){let li=active.lineById(String(id));let a=li?.siteA?.ytmId,b=li?.siteB?.ytmId;if(a!==area&&b!==area)continue;}else if(active.stationGroups.get(sidForArea)?.ytmId!==area)continue;}
 if(voltage){let v=null;if(cls==='ElmSite')v=active.stationGroups.get(String(id))?.voltageList||'';else if(cls==='ElmLne')v=active.lineById(String(id))?.voltage;else if(cls==='TypLne')v=active.value(cls,i,'uline');else if(cls==='ElmTerm')v=active.value(cls,i,'uknom');else if(cls==='ElmSubstat')v=active.stationGroups.get(sid)?.voltageList||'';else if(cls==='ElmTr2'){let r=active.row(cls,i),typ=active.get('TypTr2',r.typ_id);v=`${typ?.utrn_h} / ${typ?.utrn_l}`;}else v=active.stationGroups.get(sid)?.voltageList||'';
 if(!String(v).split(/\s*\/\s*/).includes(voltage))continue;}
 }out.push(i);}
 statState.rows=out;
}
function present(cls,row,k){if(!row)return '—';if(k==='stationA'||k==='stationB'){let val=row[k];return val&&active.stationGroups.has(val)?siteName(val):val||'—';}if(k==='station'&&typeof row[k]==='string'&&active.stationGroups.has(row[k]))return siteName(row[k]);if(k==='ytm')return row.ytm||'—';if(k==='coord')return row.coord||'—';if(k==='geoStatus')return row.geoStatus||'Eksik';return fmt(row[k]);}
function renderRows(type,table,rows,cols,cls,page,onpick){let size=+cfg.pageSize,start=page*size,part=rows.slice(start,start+size);if(!rows.length){$(table).innerHTML='<div class="empty">Filtreye uygun kayıt bulunamadı.</div>';return;}let thead=cols.map(c=>`<th>${h(LABEL[c]||c)}</th>`).join('');let tbody=part.map((r,j)=>`<tr data-idx="${start+j}">${cols.map(k=>`<td title="${h(present(cls,r,k))}">${h(present(cls,r,k))}</td>`).join('')}</tr>`).join('');$(table).innerHTML=`<table><thead><tr>${thead}</tr></thead><tbody>${tbody}</tbody></table>`;$$('tbody tr',$(table)).forEach(el=>el.onclick=()=>onpick(rows[+el.dataset.idx],el));}
function pager(id,state,reload){let max=Math.max(1,Math.ceil(state.rows.length/(+cfg.pageSize)));state.page=Math.min(max-1,Math.max(0,state.page));$(id).innerHTML=`<span class="mini">${nf.format(state.rows.length)} kayıt · ${nf.format(state.page*cfg.pageSize+ (state.rows.length?1:0))}–${nf.format(Math.min(state.rows.length,(state.page+1)*cfg.pageSize))} · Sayfa ${state.page+1}/${max}</span><div class="row"><button class="sm" data-action="prev" ${state.page===0?'disabled':''}>← Önceki</button><button class="sm" data-action="next" ${state.page>=max-1?'disabled':''}>Sonraki →</button></div>`;$$('[data-action]',$(id)).forEach(b=>b.onclick=()=>{state.page+=b.dataset.action==='next'?1:-1;reload(false)});}
function renderStatic(refilter=true){if(!active){$('staticTable').innerHTML='<div class="empty">Önce JSON dosyası yükleyin.</div>';return;}const cls=$('staticType').value||'ElmSite';if(refilter)filterStatic(true);
 let cat=CATEGORY[cls],cols=cat?.cols||active.t(cls)?.Attributes?.slice(0,20)||[];let rows=statState.rows;let part=rows.slice(statState.page*cfg.pageSize,(statState.page+1)*cfg.pageSize).map(i=>staticRow(active,cls,i));renderRows('static','staticTable',part,cols,cls,0,(r,el)=>{statState.selected=r;$$('tbody tr',$('staticTable')).forEach(e=>e.classList.remove('selected'));el.classList.add('selected');showStaticDetail(cls,r);});putText('staticStats',`${cat?.label||cls} · ${nf.format(rows.length)} eşleşen / ${nf.format(active.t(cls)?.Values.length||0)} toplam`);pager('staticPager',statState,()=>renderStatic(false));}
