function drawSeries(cls,id,kind){let fieldName=({production:'pgini',load:'plini',tap:'nntap',shunt:'ncapa',voltage:'usetp'})[kind];if(!fieldName)return;let canvas=$('seriesChart');canvas.classList.remove('hidden');const w=Math.max(350,canvas.clientWidth),hh=245,dpr=window.devicePixelRatio||1;canvas.width=w*dpr;canvas.height=hh*dpr;let g=canvas.getContext('2d');g.setTransform(dpr,0,0,dpr,0,0);g.clearRect(0,0,w,hh);let points=models.map(m=>{let r=m.get(cls,id);return{t:`${m.date} ${m.time}`,v:typeof r?.[fieldName]==='number'?r[fieldName]:null};});let valid=points.filter(x=>x.v!==null),lo=Math.min(...valid.map(x=>x.v)),hi=Math.max(...valid.map(x=>x.v));if(!valid.length){g.fillStyle='#b6cadc';g.fillText('Eşleşen veri bulunamadı.',18,32);return;}if(hi===lo){lo-=1;hi+=1;}const pad={l:61,r:20,t:27,b:48},px=i=>pad.l+i*(w-pad.l-pad.r)/Math.max(1,points.length-1),py=v=>pad.t+(hi-v)*(hh-pad.t-pad.b)/(hi-lo);g.strokeStyle='#2e5066';g.lineWidth=1;g.font='11px system-ui';g.fillStyle='#a3bdca';for(let j=0;j<=4;j++){let y=pad.t+j*(hh-pad.t-pad.b)/4;g.beginPath();g.moveTo(pad.l,y);g.lineTo(w-pad.r,y);g.stroke();g.fillText(fmt(hi-j*(hi-lo)/4),6,y+4);}g.fillText(`${LABEL[fieldName]||fieldName} · kaynağı DGS model girdisi`,pad.l,17);g.strokeStyle='#4ec9d3';g.lineWidth=2;g.beginPath();let first=true;points.forEach((p,i)=>{if(p.v===null){first=true;return;}let x=px(i),y=py(p.v);if(first)g.moveTo(x,y);else g.lineTo(x,y);first=false;});g.stroke();points.forEach((p,i)=>{if(p.v==null)return;g.beginPath();g.fillStyle='#b2f3f1';g.arc(px(i),py(p.v),3.5,0,2*Math.PI);g.fill();});let n=Math.min(6,points.length);for(let j=0;j<n;j++){let i=Math.round(j*(points.length-1)/Math.max(1,n-1));g.fillStyle='#a3bdca';g.fillText(points[i].t.split(' ')[1]||'',px(i)-16,hh-18);}}

